.maxima-scroll-root {
  height: calc((var(--stack-count) + 1) * 100svh);
  perspective: 1200px;
  position: relative;
  width: 100%;
  z-index: 1;
}
.maxima-scroll-bg {
  background: #a7eb98;
  bottom: 0;
  left: 0;
  position: absolute;
  top: 0;
  width: 100%;
}
.maxima-scroll-track {
  bottom: 0;
  height: calc(var(--stack-count) * 100svh - 50svh);
  left: 0;
  position: absolute;
  width: 100%;
}
.maxima-scroll-sticky {
  align-items: center;
  display: flex;
  height: 100svh;
  justify-content: center;
  overflow: hidden;
  position: sticky;
  top: 0;
  transform-style: preserve-3d;
  width: 100%;
}
.maxima-flip-stage {
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  width: 100%;
  will-change: transform;
}
.maxima-flip-face {
  align-items: center;
  backface-visibility: hidden;
  display: flex;
  height: 100%;
  justify-content: center;
  left: 0;
  overflow: hidden;
  position: absolute;
  top: 0;
  transform-style: preserve-3d;
  width: 100%;
}
.maxima-flip-face--back {
  transform: rotateY(180deg);
}
.maxima-cover-card {
  align-items: center;
  background: #fd4401;
  border-radius: 26px;
  box-shadow: 0 24px 70px rgba(20, 24, 40, 0.22);
  color: #fff;
  display: flex;
  flex-direction: column;
  height: 424px;
  justify-content: space-between;
  left: 50%;
  padding: 42px 38px 36px;
  position: absolute;
  text-align: center;
  top: 62svh;
  transform: translateX(-50%);
  width: 388px;
  will-change: transform;
}
.maxima-card-scene {
  height: 100%;
  position: relative;
  width: 100%;
}
.maxima-service-layer {
  align-items: center;
  backface-visibility: hidden;
  display: flex;
  height: 100svh;
  justify-content: center;
  left: 0;
  position: absolute;
  top: 0;
  width: 100%;
  will-change: transform;
}
.maxima-stack-hit {
  background: transparent;
  border: 0;
  color: inherit;
  display: block;
  padding: 0;
  pointer-events: auto;
}
.maxima-stack-nudge {
  display: block;
  will-change: transform;
}
.maxima-stack-card {
  align-items: center;
  background: var(--card-bg, white);
  border-radius: 26px;
  box-shadow: 0 24px 70px rgba(20, 24, 40, 0.22);
  color: var(--card-text, #171717);
  display: flex;
  flex-direction: column;
  height: 424px;
  justify-content: space-between;
  padding: 44px 38px 36px;
  text-align: center;
  transform-origin: center;
  width: 388px;
  will-change: transform;
}

@media (max-width: 520px) {
  .maxima-stack-card,
  .maxima-cover-card {
    width: min(78vw, 300px);
    height: 374px;
    padding: 32px 24px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .maxima-scroll-root {
    height: auto !important;
    padding: 48px 20px;
  }
  .maxima-scroll-track,
  .maxima-flip-face--front {
    display: none;
  }
  .maxima-scroll-sticky,
  .maxima-flip-stage,
  .maxima-flip-face--back,
  .maxima-card-scene,
  .maxima-service-layer {
    position: relative;
    height: auto;
    transform: none !important;
    overflow: visible;
  }
  .maxima-flip-face--back {
    backface-visibility: visible;
  }
  .maxima-card-scene {
    display: grid;
    gap: 24px;
    justify-items: center;
  }
  .maxima-service-layer {
    width: auto;
  }
  .maxima-stack-card {
    transform: none !important;
  }
}

"use client";
import {
  useEffect,
  useRef,
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
} from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { cn } from "@/lib/utils";
import "./scroll-card-stack.css";
export type ScrollStackItem = {
  id: string;
  content: ReactNode;
  background?: string;
  color?: string;
  rotation?: number;
};
export type ScrollCardStackProps = ComponentProps<"section"> & {
  items: ScrollStackItem[];
  cover: ReactNode;
  background?: string;
};
const ROTATIONS = [0.01, -11, 7, -3.82];
export function ScrollCardStack({
  items,
  cover,
  background = "#a7eb98",
  children,
  className,
  style,
  ...props
}: ScrollCardStackProps) {
  const rootRef = useRef<HTMLElement>(null);
  const rotations = items
    .map((item, i) => item.rotation ?? ROTATIONS[i % ROTATIONS.length])
    .join(",");
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    gsap.registerPlugin(ScrollTrigger);
    const match = gsap.matchMedia();
    match.add("(prefers-reduced-motion: no-preference)", () => {
      const ctx = gsap.context(() => {
        const stage = root.querySelector<HTMLElement>(".maxima-flip-stage")!;
        const coverNode =
          root.querySelector<HTMLElement>(".maxima-cover-card")!;
        const track = root.querySelector<HTMLElement>(".maxima-scroll-track")!;
        const layers = Array.from(
          root.querySelectorAll<HTMLElement>(".maxima-service-layer"),
        );
        const cards = Array.from(
          root.querySelectorAll<HTMLElement>(".maxima-stack-card"),
        );
        const angles = rotations.split(",").map(Number);
        gsap.set(cards, { rotate: 0 });
        gsap.to(coverNode, {
          y: () =>
            (window.innerHeight - coverNode.offsetHeight) / 2 -
            (parseFloat(getComputedStyle(coverNode).top) || 0),
          ease: "none",
          scrollTrigger: {
            trigger: root,
            start: "top top",
            end: () => `+=${window.innerHeight}`,
            invalidateOnRefresh: true,
            scrub: true,
          },
        });
        ScrollTrigger.create({
          trigger: root,
          start: () => `top top-=${window.innerHeight}`,
          onEnter: () => {
            gsap.to(stage, {
              rotateY: 180,
              duration: 1,
              ease: "power3.out",
              overwrite: true,
            });
            gsap.to(cards, {
              rotate: (i) => angles[i],
              delay: 0.5,
              duration: 1.2,
              ease: "elastic.out(2, 0.8)",
              overwrite: true,
            });
          },
          onLeaveBack: () => {
            gsap.to(stage, {
              rotateY: 0,
              duration: 1,
              ease: "power3.out",
              overwrite: true,
            });
            gsap.to(cards, { rotate: 0, duration: 0.6, overwrite: true });
          },
        });
        ScrollTrigger.create({
          trigger: track,
          start: "top top",
          end: "bottom center",
          scrub: true,
          onUpdate: (self) => {
            layers.forEach((layer, i) => {
              const phase = gsap.utils.clamp(
                0,
                1,
                gsap.utils.mapRange(
                  i / layers.length,
                  (i + 1.5) / layers.length,
                  0,
                  1,
                  self.progress,
                ),
              );
              gsap.to(layer, {
                yPercent: -100 * phase,
                duration: 0.8,
                ease: "elastic.out(1, 0.5)",
                overwrite: true,
              });
              gsap.to(cards[i], {
                rotate: angles[i] + phase * 40 * Math.sign(angles[i] || 1),
                duration: 0.8,
                ease: "elastic.out(1, 0.5)",
                overwrite: true,
              });
            });
          },
        });
        ScrollTrigger.refresh();
      }, root);
      return () => ctx.revert();
    });
    return () => match.revert();
  }, [rotations]);
  return (
    <section
      {...props}
      ref={rootRef}
      data-slot="scroll-card-stack"
      className={cn("maxima-scroll-root", className)}
      style={
        { background, "--stack-count": items.length, ...style } as CSSProperties
      }
    >
      {children}
      <div className="maxima-scroll-track" />
      <div className="maxima-scroll-sticky">
        <div className="maxima-flip-stage">
          <div className="maxima-flip-face maxima-flip-face--front">
            <article className="maxima-cover-card">{cover}</article>
          </div>
          <div className="maxima-flip-face maxima-flip-face--back">
            <div className="maxima-card-scene">
              {items.map((item, i) => (
                <div
                  className="maxima-service-layer"
                  key={item.id}
                  style={{ zIndex: items.length + 1 - i }}
                >
                  <article
                    className="maxima-stack-card"
                    style={
                      {
                        "--card-bg": item.background ?? "white",
                        "--card-text": item.color ?? "#171717",
                      } as CSSProperties
                    }
                  >
                    {item.content}
                  </article>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
